import numpy as np
import time


def score(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)) or np.all(h <= 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    m = L.max()
    if m <= 0:
        return -1.0
    L = np.concatenate(([0.0], L, [0.0]))
    # ||f*f||_2^2 via trapezoid on piecewise linear
    l2 = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    return l2 / (s * s * m)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best = None
    best_score = -1.0

    # Candidate starts: given start, constant, and a few shapes
    cands = []
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and np.any(s > 0):
            cands.append(np.maximum(s, 0.0))
    # constant
    cands.append(np.ones(50))
    # smooth bump shapes (Gaussian-like) of various widths
    for N in (20, 50, 100, 200, 400):
        x = np.linspace(-1, 1, N)
        for w in (0.2, 0.35, 0.5, 0.7, 1.0):
            cands.append(np.exp(-(x / w) ** 2))

    for c in cands:
        sc = score(c)
        if sc > best_score:
            best_score = sc
            best = c.copy()

    # Local search: perturb a few entries, accept improvements.
    # Use multiplicative/additive perturbation on random indices.
    rng = np.random.default_rng(12345)

    def try_improve(h, hs, iters):
        nonlocal best, best_score
        N = h.size
        cur = h.copy()
        cur_s = hs
        for _ in range(iters):
            if time.process_time() > deadline:
                return
            k = rng.integers(1, max(2, N // 10 + 2))
            idx = rng.integers(0, N, size=k)
            trial = cur.copy()
            mode = rng.random()
            if mode < 0.5:
                trial[idx] *= (1.0 + 0.3 * rng.standard_normal(k))
            else:
                trial[idx] += 0.2 * rng.standard_normal(k) * (cur.mean() + 1e-9)
            trial = np.maximum(trial, 0.0)
            if not np.any(trial > 0):
                continue
            ts = score(trial)
            if ts > cur_s:
                cur = trial
                cur_s = ts
                if ts > best_score:
                    best = trial.copy()
                    best_score = ts
        return cur, cur_s

    # multi-scale hill climbing
    if best is not None:
        # coarse then fine
        best, best_score = try_improve(best, best_score, 4000)
        if time.process_time() < deadline:
            best, best_score = try_improve(best, best_score, 4000)

    # If start existed with larger N, also try resizing via interpolation
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and time.process_time() < deadline:
            for Nnew in (s.size, max(10, s.size // 2), s.size * 2):
                if Nnew < 1 or Nnew > 50000:
                    continue
                xo = np.linspace(0, 1, s.size)
                xn = np.linspace(0, 1, Nnew)
                interp = np.maximum(np.interp(xn, xo, s), 0.0)
                sc = score(interp)
                if sc > best_score:
                    best = interp
                    best_score = sc
                    best, best_score = try_improve(best, best_score, 3000)

    if best is None:
        return np.ones(50)
    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)):
        return -np.inf
    s = h.sum()
    if s <= 0:
        return -np.inf
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    # ||f*f||_2^2
    a = L[:-1]
    b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -np.inf
    return l2sq / (l1 * linf)


def _negR(h):
    r = _R(h)
    if not np.isfinite(r):
        return 1e10
    return -r


def _upsample(start, N):
    if start is None:
        return np.ones(N)
    start = np.asarray(start, dtype=float)
    if start.size == 0:
        return np.ones(N)
    xs = np.linspace(0.0, 1.0, start.size)
    xt = np.linspace(0.0, 1.0, N)
    h = np.interp(xt, xs, start)
    if h.sum() <= 0:
        h = np.ones(N)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 5.0)

    best_h = None
    best_r = -np.inf

    # initial candidates
    candidates = []
    for N in (200, 100, 400):
        h0 = _upsample(start, N)
        candidates.append((N, h0))

    for (N, h0) in candidates:
        if time.process_time() > deadline:
            break
        bounds = [(0.0, None)] * N
        try:
            res = minimize(_negR, h0, method='L-BFGS-B', bounds=bounds,
                           options={'maxiter': 2000, 'maxfun': 200000,
                                    'ftol': 1e-12, 'gtol': 1e-10})
            h = res.x
            if h.sum() > 0:
                h = np.maximum(h, 0.0)
                r = _R(h)
                if np.isfinite(r) and r > best_r:
                    best_r = r
                    best_h = h.copy()
        except Exception:
            pass

    if best_h is None:
        best_h = _upsample(start, 200)
        best_r = _R(best_h)

    # if time remains, refine best with more iterations
    while time.process_time() < deadline:
        N = best_h.size
        bounds = [(0.0, None)] * N
        try:
            res = minimize(_negR, best_h, method='L-BFGS-B', bounds=bounds,
                           options={'maxiter': 5000, 'maxfun': 500000,
                                    'ftol': 1e-15, 'gtol': 1e-12})
            h = np.maximum(res.x, 0.0)
            if h.sum() > 0:
                r = _R(h)
                if np.isfinite(r) and r > best_r + 1e-12:
                    best_r = r
                    best_h = h.copy()
                else:
                    break
        except Exception:
            break

    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _R_parts(h):
    """Return (R, L) where L is the padded autoconvolution knots."""
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -np.inf, None
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]
    b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    linf = L.max()
    if linf <= 0:
        return -np.inf, L
    return l2sq / (s * s * linf), L


def _R(h):
    return _R_parts(h)[0]


def _upsample(start, N):
    if start is None:
        return np.ones(N)
    start = np.asarray(start, dtype=float)
    if start.size == 0:
        return np.ones(N)
    if start.size == N:
        return start.copy()
    xs = np.linspace(0.0, 1.0, start.size)
    xt = np.linspace(0.0, 1.0, N)
    h = np.interp(xt, xs, start)
    if h.sum() <= 0:
        h = np.ones(N)
    return h


def _parabolic(N, p):
    x = np.linspace(-1.0, 1.0, N)
    return np.maximum(0.0, 1.0 - np.abs(x) ** p)


def construct(budget_seconds, start):
    t0 = time.process_time()
    # leave margin
    deadline = t0 + max(0.5, budget_seconds - 6.0)

    best_h = None
    best_r = -np.inf

    def consider(h):
        nonlocal best_h, best_r
        h = np.asarray(h, dtype=float)
        h = np.maximum(h, 0.0)
        if h.sum() <= 0:
            return
        r = _R(h)
        if np.isfinite(r) and r > best_r:
            best_r = r
            best_h = h.copy()

    # 1) seed from start at its own size if possible
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            consider(s)

    # 2) parabolic family seeds (good starting shapes)
    for N in (60, 100, 150, 200, 300):
        for p in (0.5, 1.0, 1.5, 2.0, 3.0, 4.0):
            consider(_parabolic(N, p))

    # 3) local optimisation with L-BFGS-B from multiple seeds and sizes
    #    Use several sizes; the optimum seems to favor moderate N (~200).
    sizes = [100, 150, 200, 300, 400]
    seed_idx = 0
    seeds = []
    for N in sizes:
        if start is not None:
            seeds.append((N, _upsample(start, N)))
        seeds.append((N, _parabolic(N, 1.0)))
        seeds.append((N, _parabolic(N, 2.0)))

    # order seeds by current R so best get optimised first
    seeds.sort(key=lambda t: -_R(t[1]))

    for (N, h0) in seeds:
        if time.process_time() > deadline:
            break
        bounds = [(0.0, None)] * N
        try:
            res = minimize(lambda x: -_R(x), h0, method='L-BFGS-B',
                           bounds=bounds,
                           options={'maxiter': 3000, 'maxfun': 300000,
                                    'ftol': 1e-14, 'gtol': 1e-11})
            consider(res.x)
        except Exception:
            pass

    if best_h is None:
        best_h = _upsample(start, 200)
        best_r = _R(best_h)

    # 4) polish the best: iteratively re-optimise, and try small up/down sizes
    polished = best_h.copy()
    sizes_try = [polished.size]
    if polished.size < 400:
        sizes_try.append(int(polished.size * 1.5))
    if polished.size > 100:
        sizes_try.append(max(50, int(polished.size * 0.7)))

    while time.process_time() < deadline:
        improved = False
        for N in sizes_try:
            if time.process_time() > deadline:
                break
            h0 = _upsample(polished, N)
            bounds = [(0.0, None)] * N
            try:
                res = minimize(lambda x: -_R(x), h0, method='L-BFGS-B',
                               bounds=bounds,
                               options={'maxiter': 6000, 'maxfun': 600000,
                                        'ftol': 1e-15, 'gtol': 1e-12})
                r = _R(res.x)
                if np.isfinite(r) and r > best_r + 1e-13:
                    best_r = r
                    best_h = np.maximum(res.x, 0.0).copy()
                    polished = best_h.copy()
                    improved = True
            except Exception:
                pass
        if not improved:
            # try a slightly different seed by smoothing then re-optimising
            N = polished.size
            if N > 4:
                k = np.ones(3) / 3.0
                sm = np.convolve(polished, k, mode='same')
                if sm.sum() > 0:
                    bounds = [(0.0, None)] * N
                    try:
                        res = minimize(lambda x: -_R(x), sm, method='L-BFGS-B',
                                       bounds=bounds,
                                       options={'maxiter': 6000, 'maxfun': 600000,
                                                'ftol': 1e-15, 'gtol': 1e-12})
                        r = _R(res.x)
                        if np.isfinite(r) and r > best_r + 1e-13:
                            best_r = r
                            best_h = np.maximum(res.x, 0.0).copy()
                            polished = best_h.copy()
                            improved = True
                    except Exception:
                        pass
            if not improved:
                break

    return np.asarray(best_h, dtype=float)

