def _refine(h, deadline, maxiter=3000):
    N = h.size
    bounds = [(0.0, None)] * N
    try:
        res = minimize(_negR, h, method='L-BFGS-B', bounds=bounds,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 50,
                                'ftol': 1e-14, 'gtol': 1e-12})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 4.0)

    best_h = None
    best_r = -np.inf

    def consider(h):
        nonlocal best_h, best_r
        if h is None or h.size == 0:
            return
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return
        r = _R(h)
        if np.isfinite(r) and r > best_r:
            best_r = r
            best_h = h.copy()

    # Candidate starting shapes at multiple resolutions
    seed_Ns = [150, 200, 300, 400, 600]
    candidates = []
    for N in seed_Ns:
        h0 = _upsample(start, N)
        # normalized
        if h0.sum() > 0:
            h0 = h0 / h0.max()
        candidates.append(h0)

    # Refine each candidate at its own resolution
    for h0 in candidates:
        if time.process_time() > deadline:
            break
        h = _refine(h0, deadline, maxiter=1500)
        consider(h)

    if best_h is None:
        best_h = _upsample(start, 200)
        best_r = _R(best_h)

    # Iterative upsampling: refine at current N, then upsample to larger N
    N_schedule = [best_h.size, 500, 800, 1200, 1600]
    for N in N_schedule:
        if time.process_time() > deadline:
            break
        h = _upsample(best_h, N)
        if h.sum() > 0:
            h = h / h.max()
        h = _refine(h, deadline, maxiter=2000)
        consider(h)

    # Final polishing loop at best resolution
    while time.process_time() < deadline:
        N = best_h.size
        h = _refine(best_h, deadline, maxiter=4000)
        consider(h)
        # also try a small resolution bump if there's room
        if N < 2000 and time.process_time() < deadline:
            h2 = _upsample(best_h, min(N * 2, 2000))
            if h2.sum() > 0:
                h2 = h2 / h2.max()
            h2 = _refine(h2, deadline, maxiter=2000)
            consider(h2)
        else:
            break

    return np.asarray(best_h, dtype=float)

