def _negR_smooth(h, p):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)):
        return 1e10
    s = h.sum()
    if s <= 0:
        return 1e10
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
