import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)):
        return -np.inf
    s = h.sum()
    if s <= 0:
        return -np.inf
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]
    b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -np.inf
    return l2sq / (l1 * linf)


def _R_grad(h):
    """Return (R, dR/dh) analytically."""
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return -np.inf, np.zeros(n)
    c = np.convolve(h, h)
    m = c.size
    L = np.empty(m + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]
    b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    M = L.max()
    if M <= 0:
        return -np.inf, np.zeros(n)
    R = A / (l1 * M)

    gL = np.zeros(m + 2)
    gL[:-1] += (2.0 * L[:-1] + L[1:]) / 3.0
    gL[1:] += (L[:-1] + 2.0 * L[1:]) / 3.0

    gC = gL[1:-1]
    corr = np.correlate(gC, h, mode='full')
    dA_dh = 2.0 * corr[:n]

    dB_dh = 2.0 * s

    tol = 1e-9 * M
    ties = np.where(L >= M - tol)[0]
    dM_dh = np.zeros(n)
    for j in ties:
        k = j - 1
        lo = max(0, k - (n - 1))
        hi = min(n - 1, k)
        if lo <= hi:
            idx = np.arange(lo, hi + 1)
            dM_dh[idx] += 2.0 * h[k - idx]
    dM_dh /= len(ties)

    denom = l1 * M
    dR_dh = (dA_dh * denom - A * (dB_dh * M + l1 * dM_dh)) / (denom * denom)
    return R, dR_dh


def _negR_grad(h):
    R, g = _R_grad(h)
    if not np.isfinite(R):
        return 1e10, np.zeros_like(h)
    return -R, -g


def _upsample(start, N):
    if start is None:
        return np.ones(N)
    start = np.asarray(start, dtype=float)
    if start.size == 0:
        return np.ones(N)
    if start.size == N:
        return start.copy()
    xs = np.linspace(0.0, 1.0, start.size)
    xt = np.linspace(0.0, 1.0, N)
    h = np.interp(xt, xs, start)
    if h.sum() <= 0:
        h = np.ones(N)
    return h


def _refine_grad(h, deadline, maxiter=3000):
    N = h.size
    bounds = [(0.0, None)] * N
    try:
        res = minimize(_negR_grad, h, method='L-BFGS-B', bounds=bounds, jac=True,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 40,
                                'ftol': 1e-15, 'gtol': 1e-13})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 4.0)

