            # shrink right
            if b > a:
                m = mask.copy(); m[b] = False
                candidates.append(m)
            # split
            length = b - a + 1
            if length >= 4:
                mid = (a + b) // 2
                for gap in (1, 2):
                    m = mask.copy()
                    lo = mid - (gap // 2)
                    hi = lo + gap - 1
                    if lo > a and hi < b:
                        m[lo:hi + 1] = False
                        candidates.append(m)

