            if time.process_time() > deadline:
                break
            h0 = h.copy()
            h0[~m] = 0.0
            h1 = _polish_masked(h0, m, deadline, maxiter=400)
            if consider(h1):
                accepted = True
                break
            # try full polish on this candidate shape
            if time.process_time() < deadline:
                h2 = _polish(h1, deadline, maxiter=400)
                if consider(h2):
                    accepted = True
                    break

        if not accepted:
            break

    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)):
        return -np.inf
    s = h.sum()
    if s <= 0:
        return -np.inf
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    linf = L.max()
    if linf <= 0:
        return -np.inf
    return l2sq / (s * s * linf)


def _R_grad(h):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return -np.inf, np.zeros(n)
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -np.inf, np.zeros(n)
    R = l2sq / (l1 * linf)

    gL = np.zeros_like(L)
    gL[:-1] += (2.0 * a + b) / 3.0
    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = np.convolve(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]

    dl1 = 2.0 * s
    kmax = int(np.argmax(L))
    glinf_h = np.zeros(n)
    if 1 <= kmax <= 2 * n - 1:
        k = kmax - 1
        idx = np.arange(n)
        j = k - idx
        valid = (j >= 0) & (j < n)
        glinf_h[valid] = 2.0 * h[j[valid]]

    denom = l1 * linf
    gR = gl2sq / denom - l2sq * (dl1 * linf + l1 * glinf_h) / (denom * denom)
    return R, gR


def _negR_grad(h):
    R, g = _R_grad(h)
    if not np.isfinite(R):
        return 1e10, np.zeros_like(h)
    return -R, -g


def _upsample(start, N):
    if start is None:
        return np.ones(N)
    start = np.asarray(start, dtype=float)
    if start.size == 0:
        return np.ones(N)
    xs = np.linspace(0.0, 1.0, start.size)
    xt = np.linspace(0.0, 1.0, N)
    h = np.interp(xt, xs, start)
    if h.sum() <= 0:
        h = np.ones(N)
    return h


def _smooth_upsample(start, N):
    if start is None:
        return np.ones(N)
    start = np.asarray(start, dtype=float)
    if start.size == 0:
        return np.ones(N)
    xs = np.linspace(0.0, 1.0, start.size)
    xt = np.linspace(0.0, 1.0, N)
    h = np.interp(xt, xs, start)
    k = np.array([1.0, 2.0, 3.0, 2.0, 1.0]); k /= k.sum()
    h = np.convolve(h, k, mode='same')
    if h.sum() <= 0:
        h = np.ones(N)
    return h


def _polish(h, maxiter=4000):
    N = h.size
    bounds = [(0.0, None)] * N
    try:
        res = minimize(_negR_grad, h, method='L-BFGS-B', jac=True,
                       bounds=bounds,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def _mirror_half(half):
    return np.concatenate([half, half[::-1]])


def _polish_symmetric(half, maxiter=3000):
    m = half.size
    bounds = [(0.0, None)] * m

    def fun(x):
        x = np.maximum(x, 0.0)
        full = _mirror_half(x)
        R, g = _R_grad(full)
        if not np.isfinite(R):
            return 1e10, np.zeros(m)
        gh = g[:m] + g[m:][::-1]
        return -R, -gh

    try:
        res = minimize(fun, half, method='L-BFGS-B', jac=True,
                       bounds=bounds,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return half


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 2.0)

    best_h = _upsample(start, 2400)
    best_r = _R(best_h)
    if not np.isfinite(best_r):
        best_h = np.ones(2400)
        best_r = _R(best_h)

    def consider(h):
        nonlocal best_h, best_r
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return
        r = _R(h)
        if np.isfinite(r) and r > best_r:
            best_r = r
            best_h = h.copy()

    # Stage A: refine the start at its own resolution (fast, preserves its shape)
    if time.process_time() < deadline:
        h = _polish(best_h.copy(), maxiter=2000)
        consider(h)

    # Stage B: symmetric polish at medium resolution
    if time.process_time() < deadline:
        N = 2400
        full = _upsample(best_h, N)
        m = N // 2
        half = full[:m].copy()
        half = _polish_symmetric(half, maxiter=2000)
        consider(_mirror_half(half))
        if time.process_time() < deadline:
            half = _polish_symmetric(half, maxiter=2000)
            consider(_mirror_half(half))

    # Stage C: higher-resolution symmetric polish (4800 steps)
    if time.process_time() < deadline:
        N = 4800
        full = _smooth_upsample(best_h, N)
        m = N // 2
        half = full[:m].copy()
        half = _polish_symmetric(half, maxiter=1500)
        consider(_mirror_half(half))

    # Stage D: full unconstrained polish at high resolution
    if time.process_time() < deadline:
        h = _smooth_upsample(best_h, 4800)
        h = _polish(h, maxiter=2000)
        consider(h)

    # Stage E: final true polish at best's own resolution
    if time.process_time() < deadline:
        h = _polish(best_h.copy(), maxiter=3000)
        consider(h)

    return np.asarray(best_h, dtype=float)

