    if time.process_time() < deadline:
        h = _polish(best_h.copy(), maxiter=4000)
        consider(h)
        if time.process_time() < deadline:
            h = _polish(h, maxiter=4000)
            consider(h)

    # Phase 2: refine at a few resolutions with alternating smoothing.
    # Key improvement: try several N and smoothing strengths, since the
    # optimum is a delicate balance between resolution and staircase noise.
    if time.process_time() < deadline:
        base = best_h.copy()
        for N in [N0, max(N0, 2400), max(N0, 3200), N0]:
            if time.process_time() > deadline:
                break
            for sp in [0, 1]:
                if time.process_time() > deadline:
                    break
                if N == base.size:
                    h = base.copy()
                else:
                    h = _upsample(base, N)
                if sp:
                    h = _smooth(h, sp)
                h = _polish(h, maxiter=3000)
                consider(h)
                if time.process_time() < deadline:
                    h = _polish(h, maxiter=3000)
                    consider(h)

    # Phase 3: final long polish on the best
    if time.process_time() < deadline:
        h = _polish(best_h.copy(), maxiter=6000)
        consider(h)
        if time.process_time() < deadline:
            h = _polish(h, maxiter=6000)
            consider(h)

    return np.asarray(best_h, dtype=float)

