    for tol in (1e-2, 3e-3, 1e-3, 1e-4, 1e-6, 1e-9):
        if time.process_time() > deadline:
            break
        h = _polish_tol(best_h, tol, deadline, maxiter=1500)
        consider(h)

    # --- Experiment: symmetric polish at N=1600 and N=800 ---
    base_h = best_h.copy()
    base_r = best_r

    for Nsym in (1600, 800):
        if time.process_time() > deadline:
            break
        hs = _symmetrize(_upsample(base_h, Nsym))
        if hs.sum() <= 0:
            continue
        for tol in (1e-2, 1e-3, 1e-6, 1e-9):
            if time.process_time() > deadline:
