            hs = _polish_tol(hs, tol, deadline, maxiter=1500)
            hs = _symmetrize(hs)
            r = _R(hs)
            if np.isfinite(r) and r > base_r:
                base_r = r
                base_h = hs.copy()

    if base_r > best_r:
        best_h = base_h
        best_r = base_r

    return np.asarray(best_h, dtype=float)

