        if r is None:
            r = _R(h)
        if np.isfinite(r) and r > best_r:
            best_r = r
            best_h = h.copy()

    N = 1600
    h = _upsample(best_h, N)
    consider(h)

    M = 2 * N + 1
    # Top-k smoothing schedule to escape the non-smooth linf.
    k_schedule = [max(1, int(f * M)) for f in
                  (0.25, 0.15, 0.08, 0.04, 0.02, 1.0)]
    for k in k_schedule:
        if time.process_time() > deadline:
            break
        h = _polish_k(h, k, deadline, maxiter=3000)
        consider(h)
        if time.process_time() < deadline:
            h = _polish_k(best_h, k, deadline, maxiter=2000)
            consider(h)

    # True-R polish on best.
    if time.process_time() < deadline:
        h = _polish(best_h, deadline, maxiter=5000)
        consider(h)

    # Tied-max polish (spreads gradient over plateaus).
    if time.process_time() < deadline:
        h = _polish_tied(best_h, deadline, maxiter=5000)
        consider(h)

    # Fine resolution sweep then back to 1600.
    for nf in (1200, 2000, 2600, 3200):
        if time.process_time() > deadline:
