            back = _polish(back, deadline, maxiter=3000)
            consider(back)

    # Final true-R polish.
    if time.process_time() < deadline:
        h = _polish(best_h, deadline, maxiter=6000)
        consider(h)
    if time.process_time() < deadline:
        h = _polish_tied(best_h, deadline, maxiter=6000)
        consider(h)

    return np.asarray(best_h, dtype=float)

