    n = h.size
    half = n // 2
    if n % 2 == 0:
        return 0.5 * (h[:half] + h[half:][::-1])
    else:
        # odd: mirror around middle; fold pairs, keep middle
        mid = half
        left = h[:mid]
        right = h[mid + 1:][::-1]
        hh = 0.5 * (left + right)
        return np.concatenate([hh, [h[mid]], hh[::-1]])[:half + 1]


