                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def _Rk_grad(h, k):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return 1e10, np.zeros(n)
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    m = L.size
    k = max(1, min(k, m))
    idx = np.argpartition(L, m - k)[m - k:]
    lk = L[idx].mean()
    if lk <= 0:
        return 1e10, np.zeros(n)
    Rk = l2sq / (l1 * lk)

    gL = np.zeros_like(L)
    gL[:-1] += (2.0 * a + b) / 3.0
    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = np.convolve(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]

    dl1 = 2.0 * s
    glk_h = np.zeros(n)
    inv_k = 1.0 / k
    for i in idx:
        if 1 <= i <= 2 * n - 1:
            kk = i - 1
            j = kk - np.arange(n)
            valid = (j >= 0) & (j < n)
            glk_h[valid] += 2.0 * h[j[valid]] * inv_k

    denom = l1 * lk
    gRk = gl2sq / denom - l2sq * (dl1 * lk + l1 * glk_h) / (denom * denom)
    return -Rk, -gRk


def _polish_k(h, k, deadline, maxiter=3000):
    N = h.size
    bounds = [(0.0, None)] * N
    try:
        res = minimize(_Rk_grad, h, method='L-BFGS-B', jac=True,
                       bounds=bounds, args=(k,),
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 2.5)

    if start is not None:
        N0 = np.asarray(start, dtype=float).size
    else:
        N0 = 1600
    if N0 < 400:
        N0 = 400

    best_h = _upsample(start, N0)
    best_r = _R(best_h)
    if not np.isfinite(best_r):
        best_r = -np.inf

    def consider(h, r=None):
        nonlocal best_h, best_r
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return False
        if r is None:
            r = _R(h)
        if np.isfinite(r) and r > best_r:
            best_r = r
            best_h = h.copy()
            return True
        return False

    # Work at native resolution of start (possibly higher than 1600).
    N = best_h.size
    h = best_h.copy()
    consider(h)

    # Phase 1: peak-averaging homotopy (k-schedule) at native N.
    M = 2 * N + 1
    k_schedule = [max(1, int(f * M)) for f in
                  (0.30, 0.20, 0.12, 0.07, 0.03, 1.0)]
    for k in k_schedule:
        if time.process_time() > deadline:
            break
        h = _polish_k(h, k, deadline, maxiter=3000)
        consider(h)
        if time.process_time() < deadline:
            h = _polish_k(h, k, deadline, maxiter=2000)
            consider(h)

    # Phase 2: direct max-gradient polish at native N.
    if time.process_time() < deadline:
        h = _polish(best_h, deadline, maxiter=4000)
        consider(h)

    # Phase 3: tolerance homotopy (softens the max, escapes flat spots).
    for tol in (1e-2, 3e-3, 1e-3, 1e-4, 1e-6, 1e-9):
        if time.process_time() > deadline:
            break
        h = _polish_tol(best_h, tol, deadline, maxiter=1500)
        consider(h)

    # Phase 4: refinement at higher resolution, then down-polish.
    deadline2 = t0 + max(0.0, budget_seconds - 1.5)
    if time.process_time() < deadline2:
        Nhi = min(3200, 2 * N)
        h_hi = _upsample(best_h, Nhi)
        consider(h_hi)
        for tol in (1e-2, 1e-3, 1e-5, 1e-9):
            if time.process_time() >= deadline2:
                break
            h_hi = _polish_tol(h_hi, tol, deadline2, maxiter=2000)
            consider(h_hi)
        if time.process_time() < deadline2:
            h_dn = _upsample(h_hi, N)
            h_dn = _polish(h_dn, deadline2, maxiter=4000)
            consider(h_dn)

    return np.asarray(best_h, dtype=float)

