# --- Smooth-max (log-sum-exp) surrogate ---
def _softmax_L(L, T):
    # (1/T) log sum exp(T L)
    m = L.max()
    z = T * (L - m)
    # stable
    return m + np.log(np.sum(np.exp(z))) / T


def _R_soft_grad(h, T):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return 1e10, np.zeros(n)
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    m = L.max()
    z = T * (L - m)
    ez = np.exp(z)
    se = ez.sum()
    if se <= 0 or not np.isfinite(se):
        return 1e10, np.zeros(n)
    softmax = m + np.log(se) / T
    if softmax <= 0:
        return 1e10, np.zeros(n)
    R = l2sq / (l1 * softmax)

    gL = np.zeros_like(L)
    gL[:-1] += (2.0 * a + b) / 3.0
    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = np.convolve(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]

    dl1 = 2.0 * s

    # d softmax / dL_i = ez_i / se
    w = ez / se
    # d softmax / dh_j = sum_i w_i * dL_i/dh_j
    gsoft_h = np.zeros(n)
    idx = np.arange(n)
    nz = np.where(w > 1e-300)[0]
    for i in nz:
        if 1 <= i <= 2 * n - 1:
            k = i - 1
            j = k - idx
            valid = (j >= 0) & (j < n)
            gsoft_h[valid] += 2.0 * h[j[valid]] * w[i]

    denom = l1 * softmax
    gR = gl2sq / denom - l2sq * (dl1 * softmax + l1 * gsoft_h) / (denom * denom)
    return -R, -gR


