def _R(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)):
        return -np.inf
    s = h.sum()
    if s <= 0:
        return -np.inf
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    linf = L.max()
    if linf <= 0:
        return -np.inf
    return l2sq / (s * s * linf)


def _R_grad(h, rel_tol=1e-9):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return -np.inf, np.zeros(n)
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -np.inf, np.zeros(n)
    R = l2sq / (l1 * linf)

    gL = np.zeros_like(L)
    gL[:-1] += (2.0 * a + b) / 3.0
    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = np.convolve(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]

    dl1 = 2.0 * s

    glinf_h = np.zeros(n)
    active = np.where(L >= linf * (1.0 - rel_tol))[0]
    if active.size > 0:
        inv = 1.0 / active.size
        idx = np.arange(n)
        for i in active:
            if 1 <= i <= 2 * n - 1:
                k = i - 1
                j = k - idx
                valid = (j >= 0) & (j < n)
                glinf_h[valid] += 2.0 * h[j[valid]] * inv

    denom = l1 * linf
    gR = gl2sq / denom - l2sq * (dl1 * linf + l1 * glinf_h) / (denom * denom)
    return R, gR


def _negR_grad(h):
    R, g = _R_grad(h, 1e-9)
    if not np.isfinite(R):
        return 1e10, np.zeros_like(h)
    return -R, -g


def _negR_grad_tol(h, rel_tol):
    R, g = _R_grad(h, rel_tol)
    if not np.isfinite(R):
