    h = np.interp(xt, xs, start)
    if h.sum() <= 0:
        h = np.ones(N)
    return h


def _downsample(h, N):
    h = np.asarray(h, dtype=float)
    if h.size == N:
        return h.copy()
    xs = np.linspace(0.0, 1.0, h.size)
    xt = np.linspace(0.0, 1.0, N)
    out = np.interp(xt, xs, h)
    if out.sum() <= 0:
        out = np.ones(N)
    return out


def _polish(h, deadline, maxiter=4000):
    N = h.size
    bounds = [(0.0, None)] * N
    try:
        res = minimize(_negR_grad, h, method='L-BFGS-B', jac=True,
