        return h


def _polish_tol(h, rel_tol, deadline, maxiter=1500):
    N = h.size
    bounds = [(0.0, None)] * N
    try:
        res = minimize(_negR_grad_tol, h, method='L-BFGS-B', jac=True,
                       bounds=bounds, args=(rel_tol,),
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def _unfold(hh):
    hh = np.asarray(hh, dtype=float)
    return np.concatenate([hh, hh[::-1]])


def _fold(h):
    h = np.asarray(h, dtype=float)
    n = h.size
    half = n // 2
    if n % 2 == 0:
        return 0.5 * (h[:half] + h[half:][::-1])
    else:
        mid = half
        left = h[:mid]
        right = h[mid + 1:][::-1]
        hh = 0.5 * (left + right)
        return np.concatenate([hh, [h[mid]], hh[::-1]])[:half + 1]


