    h = _unfold(hh)
    R, g = _R_grad(h, rel_tol)
    if not np.isfinite(R):
        return 1e10, np.zeros_like(hh)
    n = h.size
    half = n // 2
    g_hh = g[:half] + g[half:][::-1]
    return -R, -g_hh


