    gl2sq = 2.0 * conv[n - 1: n - 1 + n]

    dl1 = 2.0 * s
    glk_h = np.zeros(n)
    inv_k = 1.0 / k
    for i in idx:
        if 1 <= i <= 2 * n - 1:
            kk = i - 1
            j = kk - np.arange(n)
            valid = (j >= 0) & (j < n)
            glk_h[valid] += 2.0 * h[j[valid]] * inv_k

