# --- Coarse parametric symmetric family: 11 knots on [0,1] ---
_KNOTS = np.linspace(0.0, 1.0, 11)


def _coarse_to_h(coef, N):
    coef = np.asarray(coef, dtype=float)
    xt = np.linspace(0.0, 1.0, N)
    h = np.interp(xt, _KNOTS, coef)
    return np.maximum(h, 0.0)


def _coarse_negR(coef):
    h = _coarse_to_h(coef, 400)
    r = _R(h)
    if not np.isfinite(r):
        return 1e10
    return -r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 2.5)

    best_h = _upsample(start, 1600)
    best_r = _R(best_h)
    if not np.isfinite(best_r):
        best_r = -np.inf

    def consider(h, r=None):
        nonlocal best_h, best_r
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return
        if r is None:
            r = _R(h)
        if np.isfinite(r) and r > best_r:
            best_r = r
            best_h = h.copy()

    # --- Coarse parametric search with differential evolution ---
    candidates = []
    try:
        bounds = [(0.0, 2.0)] * 11
        res = differential_evolution(
            _coarse_negR, bounds, seed=0, popsize=15, maxiter=50,
            polish=False, tol=1e-6, mutation=(0.5, 1.0), recombination=0.7,
            init='latinhypercube')
        candidates.append(np.asarray(res.x, dtype=float))
        # Also collect a few from the final population if available
        try:
            pop = res.population
            energies = res.population_energies
            order = np.argsort(energies)
            for oi in order[:3]:
                candidates.append(np.asarray(pop[oi], dtype=float))
        except Exception:
            pass
    except Exception:
        pass

    # Deduplicate candidates, keep the best few
    uniq = []
    for c in candidates:
        if not any(np.allclose(c, u, atol=1e-6) for u in uniq):
            uniq.append(c)
    uniq.sort(key=lambda c: _coarse_negR(c))
    uniq = uniq[:3]

    # Polish each candidate at N=1600 with annealed rel_tol
    for coef in uniq:
        if time.process_time() > deadline:
            break
        h = _coarse_to_h(coef, 1600)
        consider(h)
        for tol in (1e-2, 3e-3, 1e-3, 1e-4, 1e-6, 1e-9):
            if time.process_time() > deadline:
                break
            h = _polish_tol(h, tol, deadline, maxiter=1000)
            consider(h)

    # --- Symmetric search from folded best (safety / refinement) ---
    if time.process_time() < deadline:
        hh = _fold(best_h)
        consider(_unfold(hh))
        for tol in (1e-2, 3e-3, 1e-3, 1e-4, 1e-6, 1e-9):
            if time.process_time() > deadline:
                break
            hh = _polish_sym(hh, tol, deadline, maxiter=1000)
            consider(_unfold(hh))

    # --- Full pipeline from best_h as safety net ---
    if time.process_time() < deadline:
        h = _polish(best_h, deadline, maxiter=2000)
        consider(h)
    for tol in (1e-2, 3e-3, 1e-3, 1e-4, 1e-6, 1e-9):
        if time.process_time() > deadline:
            break
        h = _polish_tol(best_h, tol, deadline, maxiter=1000)
        consider(h)

    return np.asarray(best_h, dtype=float)

