    except Exception:
        return h


def _symmetrize(h):
    h = np.asarray(h, dtype=float)
    return 0.5 * (h + h[::-1])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 2.5)

    def timeleft():
        return time.process_time() < deadline

    best_h = _upsample(start, 1600)
    best_r = _R(best_h)
    if not np.isfinite(best_r):
        best_r = -np.inf

    def consider(h, r=None):
        nonlocal best_h, best_r
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return False
        if r is None:
            r = _R(h)
        if np.isfinite(r) and r > best_r:
            best_r = r
            best_h = h.copy()
            return True
        return False

    consider(best_h)

    # Phase A: softmax/anneal via top-k to escape flat maximum
    N = 1600
    M = 2 * N + 1
    h = _upsample(best_h, N)
    for f in (0.20, 0.10, 0.05, 0.02, 1.0):
        if not timeleft():
            break
        k = max(1, int(f * M))
        h = _polish_k(h, k, maxiter=2500)
        consider(h)

    # Phase B: direct polish at various tolerances
    for tol in (1e-2, 3e-3, 1e-3, 1e-4, 1e-6, 1e-9):
        if not timeleft():
            break
        h = _polish_tol(best_h, tol, maxiter=1500)
        consider(h)

    # Phase C: symmetric polish at multiple resolutions
    base_h = best_h.copy()
    base_r = best_r
    for Nsym in (1600, 800, 2400):
        if not timeleft():
            break
        hs = _symmetrize(_upsample(base_h, Nsym))
        if hs.sum() <= 0:
            continue
        for tol in (1e-2, 1e-3, 1e-6, 1e-9):
            if not timeleft():
                break
            hs = _polish_tol(hs, tol, maxiter=1500)
            hs = _symmetrize(hs)
            r = _R(hs)
            if np.isfinite(r) and r > base_r:
                base_r = r
                base_h = hs.copy()

    if base_r > best_r:
        best_h = base_h
        best_r = base_r

    # Phase D: fine upsampling + polish (higher resolution final push)
    for Nf in (3200, 2400, 2000):
        if not timeleft():
            break
        hf = _upsample(best_h, Nf)
        hf = _polish(hf, maxiter=3000)
        if consider(hf):
            # try to re-symmetrize at high resolution
            if timeleft():
                hf2 = _symmetrize(hf)
                hf2 = _polish_tol(hf2, 1e-6, maxiter=1500)
                consider(hf2)

    # Phase E: final direct polish
    if timeleft():
        h = _polish(best_h, maxiter=4000)
        consider(h)

    return np.asarray(best_h, dtype=float)

