import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)):
        return -np.inf
    s = h.sum()
    if s <= 0:
        return -np.inf
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    linf = L.max()
    if linf <= 0:
        return -np.inf
    return l2sq / (s * s * linf)


def _R_grad(h, rel_tol=1e-9):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return -np.inf, np.zeros(n)
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -np.inf, np.zeros(n)
    R = l2sq / (l1 * linf)

    gL = np.zeros_like(L)
    gL[:-1] += (2.0 * a + b) / 3.0
    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = np.convolve(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]

    dl1 = 2.0 * s

    glinf_h = np.zeros(n)
    active = np.where(L >= linf * (1.0 - rel_tol))[0]
    if active.size > 0:
        inv = 1.0 / active.size
        idx = np.arange(n)
        for i in active:
            if 1 <= i <= 2 * n - 1:
                k = i - 1
                j = k - idx
                valid = (j >= 0) & (j < n)
                glinf_h[valid] += 2.0 * h[j[valid]] * inv

    denom = l1 * linf
    gR = gl2sq / denom - l2sq * (dl1 * linf + l1 * glinf_h) / (denom * denom)
    return R, gR


def _negR_grad(h):
    R, g = _R_grad(h, 1e-9)
    if not np.isfinite(R):
        return 1e10, np.zeros_like(h)
    return -R, -g


def _negR_grad_tol(h, rel_tol):
    R, g = _R_grad(h, rel_tol)
    if not np.isfinite(R):
        return 1e10, np.zeros_like(h)
    return -R, -g


def _negR_grad_soft(h, alpha):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return 1e10, np.zeros(n)
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    mx = L.max()
    e = np.exp((L - mx) / alpha)
    Z = e.sum()
    linf = (e * L).sum() / Z
    if linf <= 0:
        return 1e10, np.zeros(n)
    R = l2sq / (l1 * linf)

    gL = np.zeros_like(L)
    gL[:-1] += (2.0 * a + b) / 3.0
    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = np.convolve(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]

    dlinf = e * (L - linf + alpha) / (alpha * Z)
    dlinf_c = dlinf[1:-1]
    conv2 = np.convolve(dlinf_c, h[::-1])
    glinf_h = 2.0 * conv2[n - 1: n - 1 + n]

    dl1 = 2.0 * s
    denom = l1 * linf
    gR = gl2sq / denom - l2sq * (dl1 * linf + l1 * glinf_h) / (denom * denom)
    return -R, -gR


def _upsample(start, N):
    if start is None:
        return np.ones(N)
    start = np.asarray(start, dtype=float)
    if start.size == 0:
        return np.ones(N)
    if start.size == N:
        return start.copy()
    xs = np.linspace(0.0, 1.0, start.size)
    xt = np.linspace(0.0, 1.0, N)
    h = np.interp(xt, xs, start)
    if h.sum() <= 0:
        h = np.ones(N)
    return h


def _polish(h, maxiter=4000):
    N = h.size
    bounds = [(0.0, None)] * N
    try:
        res = minimize(_negR_grad, h, method='L-BFGS-B', jac=True,
                       bounds=bounds,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def _polish_tol(h, rel_tol, maxiter=1500):
    N = h.size
    bounds = [(0.0, None)] * N
    try:
        res = minimize(_negR_grad_tol, h, method='L-BFGS-B', jac=True,
                       bounds=bounds, args=(rel_tol,),
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def _polish_soft(h, alpha, maxiter=1500):
    N = h.size
    bounds = [(0.0, None)] * N
    try:
        res = minimize(_negR_grad_soft, h, method='L-BFGS-B', jac=True,
                       bounds=bounds, args=(alpha,),
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def _polish_masked(h, mask, maxiter=600):
    h = np.asarray(h, dtype=float).copy()
    free = np.where(mask)[0]
    if free.size == 0:
        return h
    base = np.zeros_like(h)
    x0 = h[free].copy()

    def fg(x):
        v = base.copy()
        v[free] = x
        R, g = _R_grad(v, 1e-9)
        if not np.isfinite(R):
            return 1e10, np.zeros_like(x)
        return -R, -g[free]

    try:
        res = minimize(fg, x0, method='L-BFGS-B', jac=True,
                       bounds=[(0.0, None)] * free.size,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        out = base.copy()
        out[free] = np.maximum(res.x, 0.0)
        return out
    except Exception:
        return h


def _runs(mask):
    runs = []
    n = mask.size
    i = 0
    while i < n:
        if mask[i]:
            j = i
            while j < n and mask[j]:
                j += 1
            runs.append((i, j - 1))
            i = j
        else:
            i += 1
    return runs


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 3.0)

    # Start from the provided solution if available, else ones.
    if start is not None and np.asarray(start).size > 0:
        best_h = np.maximum(np.asarray(start, dtype=float), 0.0)
    else:
        best_h = np.ones(400)
    best_r = _R(best_h)
    if not np.isfinite(best_r):
        best_r = -np.inf
        best_h = np.ones(400)
        best_r = _R(best_h)

    def consider(h, r=None):
        nonlocal best_h, best_r
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return False
        if r is None:
            r = _R(h)
        if np.isfinite(r) and r > best_r:
            best_r = r
            best_h = h.copy()
            return True
        return False

    N0 = best_h.size

    # Phase A: softmax anneal at native N, ping-pong with hard polishes.
    alphas = np.geomspace(0.1, 1e-5, 22)
    for alpha in alphas:
        if time.process_time() > deadline:
            break
        h = _polish_soft(best_h, alpha, maxiter=400)
        consider(h)
        if time.process_time() > deadline:
            break
        h = _polish_tol(h, 1e-3, maxiter=300)
        consider(h)
        if time.process_time() > deadline:
            break
        h = _polish_tol(h, 1e-8, maxiter=300)
        consider(h)

    # Phase B: try a larger N (upsample) and re-anneal briefly.
    for N_big in (int(N0 * 1.5), int(N0 * 2.0)):
        if time.process_time() > deadline:
            break
        if N_big > 50000:
            break
        hB = _upsample(best_h, N_big)
        consider(hB)
        for alpha in alphas[::2]:
            if time.process_time() > deadline:
                break
            hB = _polish_soft(hB, alpha, maxiter=250)
            consider(hB)
            if time.process_time() > deadline:
                break
            hB = _polish_tol(hB, 1e-8, maxiter=250)
            consider(hB)
        # hard polish
        if time.process_time() < deadline:
            hB = _polish(best_h if best_h.size == N_big else _upsample(best_h, N_big),
                         maxiter=1500)
            consider(hB)

    # Phase C: support search (extend/shrink/split runs).
    while time.process_time() < deadline:
        h = best_h
        n = h.size
        thr = 1e-6 * max(h.max(), 1e-30)
        mask = h > thr
        runs = _runs(mask)
        if not runs:
            break
        accepted = False

        candidates = []
        for (a, b) in runs:
            if a - 1 >= 0:
                m = mask.copy(); m[a - 1] = True
                candidates.append(m)
            if b + 1 < n:
                m = mask.copy(); m[b + 1] = True
                candidates.append(m)
            if b > a:
                m = mask.copy(); m[a] = False
                candidates.append(m)
                m = mask.copy(); m[b] = False
                candidates.append(m)
            length = b - a + 1
            if length >= 4:
                mid = (a + b) // 2
                for gap in (1, 2):
                    m = mask.copy()
                    lo = mid - (gap // 2)
                    hi = lo + gap - 1
                    if lo > a and hi < b:
                        m[lo:hi + 1] = False
                        candidates.append(m)

        for m in candidates:
            if time.process_time() > deadline:
                break
            h0 = h.copy()
            h0[~m] = 0.0
            h1 = _polish_masked(h0, m, maxiter=400)
            if consider(h1):
                accepted = True
                break
            if time.process_time() < deadline:
                h2 = _polish(h1, maxiter=400)
                if consider(h2):
                    accepted = True
                    break

        if not accepted:
            break

    # Final: polish the best with all methods once more.
    if time.process_time() < deadline:
        h = _polish(best_h, maxiter=3000)
        consider(h)
    if time.process_time() < deadline:
        h = _polish_tol(best_h, 1e-8, maxiter=2000)
        consider(h)

    return np.asarray(best_h, dtype=float)

