def _Rk_grad(h, k):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return 1e10, np.zeros(n)
    c = _conv(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    m = L.size
    k = max(1, min(k, m))
    idx = np.argpartition(L, m - k)[m - k:]
    lk = L[idx].mean()
    if lk <= 0:
        return 1e10, np.zeros(n)
    Rk = l2sq / (l1 * lk)

    gL = np.zeros_like(L)
    gL[:-1] += (2.0 * a + b) / 3.0
    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = _conv(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]

    dl1 = 2.0 * s
    glk_h = np.zeros(n)
    inv_k = 1.0 / k
    for i in idx:
        if 1 <= i <= 2 * n - 1:
            kk = i - 1
            j = kk - np.arange(n)
            valid = (j >= 0) & (j < n)
            glk_h[valid] += 2.0 * h[j[valid]] * inv_k

    denom = l1 * lk
    gRk = gl2sq / denom - l2sq * (dl1 * lk + l1 * glk_h) / (denom * denom)
    return -Rk, -gRk


def _polish_k(h, k, maxiter=3000):
    N = h.size
    bounds = [(0.0, None)] * N
    try:
        res = minimize(_Rk_grad, h, method='L-BFGS-B', jac=True,
                       bounds=bounds, args=(k,),
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 3.0)

    best_h = _upsample(start, 1600)
    best_r = _R(best_h)
    if not np.isfinite(best_r):
        best_r = -np.inf

    def consider(h, r=None):
        nonlocal best_h, best_r
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return False
        if r is None:
            r = _R(h)
        if np.isfinite(r) and r > best_r:
            best_r = r
            best_h = h.copy()
            return True
        return False

    N = 1600
    M = 2 * N + 1

    # Fast, targeted polish ladder from start.
    for tol in (1e-3, 1e-5, 1e-7, 1e-9, 1e-10):
        if time.process_time() > deadline:
            break
        h = _polish_tol(best_h, tol, maxiter=800)
        consider(h)

    for alpha in np.geomspace(3e-4, 1e-7, 10):
        if time.process_time() > deadline:
            break
        h = _polish_soft(best_h, alpha, maxiter=800)
        consider(h)
        if time.process_time() > deadline:
            break
        h = _polish_tol(h, 1e-10, maxiter=500)
        consider(h)

    if time.process_time() < deadline:
        h = _polish(best_h, maxiter=2500)
        consider(h)

    # Top-k annealing at the same N.
    for f in (0.30, 0.20, 0.12, 0.07, 0.04, 0.02, 0.01, 1.0):
        if time.process_time() > deadline:
            break
        k = max(1, int(f * M))
        h = _polish_k(best_h, k, maxiter=800)
        consider(h)
        if time.process_time() > deadline:
            break
        h = _polish_tol(best_h, 1e-9, maxiter=400)
        consider(h)

    # Try higher N: upsample then polish, keeping the higher-N if better.
    for N2 in (2000, 2400, 2800, 3200):
        if time.process_time() > deadline:
            break
        h2 = _upsample(best_h, N2)
        consider(h2)
        for f in (0.10, 0.05, 0.02, 1.0):
            if time.process_time() > deadline:
                break
            k = max(1, int(f * (2 * N2 + 1)))
            h2 = _polish_k(h2, k, maxiter=600)
            consider(h2)
        if time.process_time() < deadline:
            h2 = _polish_tol(h2, 1e-9, maxiter=600)
            consider(h2)
        if time.process_time() < deadline:
            h2 = _polish(h2, maxiter=800)
            consider(h2)

    # Final exact-R polish.
    if time.process_time() < deadline:
        h = _polish(best_h, maxiter=1500)
        consider(h)

    # --- Experiment: coarse multistart at N=400, then upsample+polish ---
    Nc = 400
    # Downsample best_h to Nc by block-averaging.
    bh = np.asarray(best_h, dtype=float)
    if bh.size % Nc == 0:
        coarse0 = bh.reshape(Nc, -1).mean(axis=1)
    else:
        coarse0 = np.interp(np.linspace(0.0, 1.0, Nc),
                            np.linspace(0.0, 1.0, bh.size), bh)
    if coarse0.sum() <= 0:
        coarse0 = np.ones(Nc)

    rng = np.random.RandomState(12345)
    best_coarse = coarse0.copy()
    best_coarse_r = _R(best_coarse)
    if not np.isfinite(best_coarse_r):
        best_coarse_r = -np.inf

    maxamp = coarse0.max() if coarse0.max() > 0 else 1.0
    xgrid = np.linspace(0.0, 1.0, Nc)

    for trial in range(30):
        if time.process_time() > deadline:
            break
        if trial % 3 == 2:
            # additive low-frequency sinusoid noise
            freq = rng.uniform(1.0, 4.0)
            phase = rng.uniform(0.0, 2.0 * np.pi)
            pert = coarse0 + 0.1 * maxamp * np.sin(2.0 * np.pi * freq * xgrid + phase)
        else:
            pert = coarse0 * (1.0 + 0.05 * rng.randn(Nc))
        pert = np.maximum(pert, 0.0)
        if pert.sum() <= 0:
            continue
        hc = _polish(pert, maxiter=1000)
        rc = _R(hc)
        if np.isfinite(rc) and rc > best_coarse_r:
            best_coarse_r = rc
            best_coarse = hc.copy()

    # Upsample best coarse to N=1600 and N=3200, polish, consider.
    for Nt in (1600, 3200):
        if time.process_time() > deadline:
            break
        ht = np.interp(np.linspace(0.0, 1.0, Nt),
                       np.linspace(0.0, 1.0, Nc), best_coarse)
        if ht.sum() <= 0:
            continue
        consider(ht)
        if time.process_time() < deadline:
            ht = _polish_tol(ht, 1e-10, maxiter=1500)
            consider(ht)
        if time.process_time() < deadline:
            ht = _polish(ht, maxiter=2000)
            consider(ht)

    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(a, b):
    if a.size > 2000 or b.size > 2000:
        return fftconvolve(a, b)
    return np.convolve(a, b)


def _R(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)):
        return -np.inf
    s = h.sum()
    if s <= 0:
        return -np.inf
    c = _conv(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    linf = L.max()
    if linf <= 0:
        return -np.inf
    return l2sq / (s * s * linf)


def _R_grad(h, rel_tol=1e-9):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return -np.inf, np.zeros(n)
    c = _conv(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -np.inf, np.zeros(n)
    R = l2sq / (l1 * linf)

    gL = np.zeros_like(L)
    gL[:-1] += (2.0 * a + b) / 3.0
    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = _conv(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]

    dl1 = 2.0 * s

    glinf_h = np.zeros(n)
    active = np.where(L >= linf * (1.0 - rel_tol))[0]
    if active.size > 0:
        inv = 1.0 / active.size
        idx = np.arange(n)
        for i in active:
            if 1 <= i <= 2 * n - 1:
                k = i - 1
                j = k - idx
                valid = (j >= 0) & (j < n)
                glinf_h[valid] += 2.0 * h[j[valid]] * inv

    denom = l1 * linf
    gR = gl2sq / denom - l2sq * (dl1 * linf + l1 * glinf_h) / (denom * denom)
    return R, gR


def _negR_grad(h):
    R, g = _R_grad(h, 1e-9)
    if not np.isfinite(R):
        return 1e10, np.zeros_like(h)
    return -R, -g


def _negR_grad_tol(h, rel_tol):
    R, g = _R_grad(h, rel_tol)
    if not np.isfinite(R):
        return 1e10, np.zeros_like(h)
    return -R, -g


def _negR_grad_soft(h, alpha):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return 1e10, np.zeros(n)
    c = _conv(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    mx = L.max()
    e = np.exp((L - mx) / alpha)
    Z = e.sum()
    linf = (e * L).sum() / Z
    if linf <= 0:
        return 1e10, np.zeros(n)
    R = l2sq / (l1 * linf)

    gL = np.zeros_like(L)
    gL[:-1] += (2.0 * a + b) / 3.0
    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = _conv(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]

    dlinf = e * (L - linf + alpha) / (alpha * Z)
    dlinf_c = dlinf[1:-1]
    conv2 = _conv(dlinf_c, h[::-1])
    glinf_h = 2.0 * conv2[n - 1: n - 1 + n]

    dl1 = 2.0 * s
    denom = l1 * linf
    gR = gl2sq / denom - l2sq * (dl1 * linf + l1 * glinf_h) / (denom * denom)
    return -R, -gR


def _upsample(start, N):
    if start is None:
        return np.ones(N)
    start = np.asarray(start, dtype=float)
    if start.size == 0:
        return np.ones(N)
    xs = np.linspace(0.0, 1.0, start.size)
    xt = np.linspace(0.0, 1.0, N)
    h = np.interp(xt, xs, start)
    if h.sum() <= 0:
        h = np.ones(N)
    return h


def _polish(h, maxiter=4000):
    N = h.size
    bounds = [(0.0, None)] * N
    try:
        res = minimize(_negR_grad, h, method='L-BFGS-B', jac=True,
                       bounds=bounds,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def _polish_tol(h, rel_tol, maxiter=1500, bounds=None):
    N = h.size
    if bounds is None:
        bounds = [(0.0, None)] * N
    try:
        res = minimize(_negR_grad_tol, h, method='L-BFGS-B', jac=True,
                       bounds=bounds, args=(rel_tol,),
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def _polish_soft(h, alpha, maxiter=1500, bounds=None):
    N = h.size
    if bounds is None:
        bounds = [(0.0, None)] * N
    try:
        res = minimize(_negR_grad_soft, h, method='L-BFGS-B', jac=True,
                       bounds=bounds, args=(alpha,),
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def _Rk_grad(h, k):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
