    l1 = s * s
    m = L.size
    k = max(1, min(k, m))
    idx = np.argpartition(L, m - k)[m - k:]
    lk = L[idx].mean()
    if lk <= 0:
        return 1e10, np.zeros(n)
    Rk = l2sq / (l1 * lk)

    gL = np.zeros_like(L)
    gL[:-1] += (2.0 * a + b) / 3.0
    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = _conv(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]

    dl1 = 2.0 * s
    glk_h = np.zeros(n)
    inv_k = 1.0 / k
    for i in idx:
        if 1 <= i <= 2 * n - 1:
            kk = i - 1
            j = kk - np.arange(n)
            valid = (j >= 0) & (j < n)
            glk_h[valid] += 2.0 * h[j[valid]] * inv_k

    denom = l1 * lk
    gRk = gl2sq / denom - l2sq * (dl1 * lk + l1 * glk_h) / (denom * denom)
    return -Rk, -gRk


def _polish_k(h, k, maxiter=3000):
    N = h.size
    bounds = [(0.0, None)] * N
    try:
        res = minimize(_Rk_grad, h, method='L-BFGS-B', jac=True,
                       bounds=bounds, args=(k,),
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


# --- Symmetric parametrization helpers ---
def _sym_to_h(u):
    u = np.asarray(u, dtype=float)
    return np.concatenate([u, u[::-1]])


def _negR_sym_grad(u, rel_tol=1e-9):
    h = _sym_to_h(u)
    R, g = _R_grad(h, rel_tol)
    if not np.isfinite(R):
        return 1e10, np.zeros_like(u)
    n = h.size
    gu = g[:n // 2] + g[n - 1: n - 1 - n // 2: -1]
    return -R, -gu


def _negR_sym_soft_grad(u, alpha):
    h = _sym_to_h(u)
    negR, g = _negR_grad_soft(h, alpha)
    if not np.isfinite(negR):
        return 1e10, np.zeros_like(u)
    n = h.size
    gu = g[:n // 2] + g[n - 1: n - 1 - n // 2: -1]
    return negR, -gu


def _polish_sym(u, rel_tol=1e-9, maxiter=3000):
    bounds = [(0.0, None)] * u.size
    try:
        res = minimize(_negR_sym_grad, u, method='L-BFGS-B', jac=True,
                       bounds=bounds, args=(rel_tol,),
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return u


def _polish_sym_soft(u, alpha, maxiter=1500):
    bounds = [(0.0, None)] * u.size
    try:
        res = minimize(_negR_sym_soft_grad, u, method='L-BFGS-B', jac=True,
                       bounds=bounds, args=(alpha,),
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return u


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 3.0)

    best_h = _upsample(start, 1600)
    best_r = _R(best_h)
    if not np.isfinite(best_r):
        best_r = -np.inf

    def consider(h, r=None):
        nonlocal best_h, best_r
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return False
        if r is None:
            r = _R(h)
        if np.isfinite(r) and r > best_r:
            best_r = r
            best_h = h.copy()
            return True
        return False

    N = 1600
    M = 2 * N + 1

    # Fast, targeted polish ladder from start.
    for tol in (1e-3, 1e-5, 1e-7, 1e-9, 1e-10):
        if time.process_time() > deadline:
            break
        h = _polish_tol(best_h, tol, maxiter=800)
        consider(h)

    for alpha in np.geomspace(3e-4, 1e-7, 10):
        if time.process_time() > deadline:
            break
        h = _polish_soft(best_h, alpha, maxiter=800)
        consider(h)
        if time.process_time() > deadline:
            break
        h = _polish_tol(h, 1e-10, maxiter=500)
        consider(h)

    if time.process_time() < deadline:
        h = _polish(best_h, maxiter=2500)
        consider(h)

    # Top-k annealing at the same N.
    for f in (0.30, 0.20, 0.12, 0.07, 0.04, 0.02, 0.01, 1.0):
        if time.process_time() > deadline:
            break
        k = max(1, int(f * M))
        h = _polish_k(best_h, k, maxiter=800)
        consider(h)
        if time.process_time() > deadline:
            break
        h = _polish_tol(best_h, 1e-9, maxiter=400)
        consider(h)

    # Try higher N: upsample then polish, keeping the higher-N if better.
    for N2 in (2000, 2400, 2800, 3200):
        if time.process_time() > deadline:
            break
        h2 = _upsample(best_h, N2)
        consider(h2)
        for f in (0.10, 0.05, 0.02, 1.0):
            if time.process_time() > deadline:
                break
            k = max(1, int(f * (2 * N2 + 1)))
            h2 = _polish_k(h2, k, maxiter=600)
            consider(h2)
        if time.process_time() < deadline:
            h2 = _polish_tol(h2, 1e-9, maxiter=600)
            consider(h2)
        if time.process_time() < deadline:
            h2 = _polish(h2, maxiter=800)
            consider(h2)

    # Final exact-R polish.
    if time.process_time() < deadline:
        h = _polish(best_h, maxiter=1500)
        consider(h)

    # --- Experiment: exact replication to finer grids, frozen zeros ---
    def refine(base_h, factor):
        h2 = np.repeat(np.asarray(base_h, dtype=float), factor)
        r0 = _R(base_h)
        r2 = _R(h2)
        if not (np.isfinite(r2) and abs(r2 - r0) <= 1e-9 * max(1.0, abs(r0))):
            pass
        consider(h2, r2)
        bounds = [(0.0, 0.0) if h2[i] == 0.0 else (0.0, None)
                  for i in range(h2.size)]
        cur = h2
        for tol in (1e-5, 1e-9, 1e-10):
            if time.process_time() > deadline:
                return
            cur = _polish_tol(cur, tol, maxiter=400, bounds=bounds)
            consider(cur)
        for alpha in (1e-5, 1e-6, 1e-7):
            if time.process_time() > deadline:
                return
            cur = _polish_soft(cur, alpha, maxiter=400, bounds=bounds)
            consider(cur)

    if time.process_time() < deadline:
        refine(best_h, 2)
    if time.process_time() < deadline:
        refine(best_h, 4)

    # --- Experiment: reflection-symmetric ascent ---
    # (a) symmetrize current best and consider it
    h_sym = 0.5 * (best_h + best_h[::-1])
    r_sym = _R(h_sym)
    r_best_before = best_r
    consider(h_sym, r_sym)
    try:
        print("sym check: R(h_sym)=%.12f  R(best)=%.12f  diff=%.3e"
              % (r_sym, r_best_before, r_sym - r_best_before))
    except Exception:
        pass

    # (b) symmetric parametrized polish at N=1600 and N=3200
    for Ns in (1600, 3200):
        if time.process_time() > deadline:
            break
        hs = _upsample(best_h, Ns)
        # symmetrize the starting point
        u = 0.5 * (hs[:Ns // 2] + hs[Ns - 1: Ns - 1 - Ns // 2: -1])
        u = np.maximum(u, 0.0)
        consider(_sym_to_h(u))
        # tol ladder
        for tol in (1e-5, 1e-7, 1e-9, 1e-10):
            if time.process_time() > deadline:
                break
            u = _polish_sym(u, rel_tol=tol, maxiter=3000)
            consider(_sym_to_h(u))
        # softmax ladder
        for alpha in (1e-5, 1e-6, 1e-7):
            if time.process_time() > deadline:
                break
