import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(a, b):
    if a.size > 2000 or b.size > 2000:
        return fftconvolve(a, b)
    return np.convolve(a, b)


def _R(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)):
        return -np.inf
    s = h.sum()
    if s <= 0:
        return -np.inf
    c = _conv(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    linf = L.max()
    if linf <= 0:
        return -np.inf
    return l2sq / (s * s * linf)


def _R_grad(h, rel_tol=1e-9):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return -np.inf, np.zeros(n)
    c = _conv(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -np.inf, np.zeros(n)
    R = l2sq / (l1 * linf)

    gL = np.zeros_like(L)
    gL[:-1] += (2.0 * a + b) / 3.0
    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = _conv(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]

    dl1 = 2.0 * s

    glinf_h = np.zeros(n)
    active = np.where(L >= linf * (1.0 - rel_tol))[0]
    if active.size > 0:
        inv = 1.0 / active.size
        idx = np.arange(n)
        for i in active:
            if 1 <= i <= 2 * n - 1:
                k = i - 1
                j = k - idx
                valid = (j >= 0) & (j < n)
                glinf_h[valid] += 2.0 * h[j[valid]] * inv

    denom = l1 * linf
    gR = gl2sq / denom - l2sq * (dl1 * linf + l1 * glinf_h) / (denom * denom)
    return R, gR


def _negR_grad(h):
    R, g = _R_grad(h, 1e-9)
    if not np.isfinite(R):
        return 1e10, np.zeros_like(h)
    return -R, -g


def _negR_grad_tol(h, rel_tol):
    R, g = _R_grad(h, rel_tol)
    if not np.isfinite(R):
        return 1e10, np.zeros_like(h)
    return -R, -g


def _negR_grad_soft(h, alpha):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return 1e10, np.zeros(n)
    c = _conv(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    mx = L.max()
    e = np.exp((L - mx) / alpha)
    Z = e.sum()
    linf = (e * L).sum() / Z
    if linf <= 0:
        return 1e10, np.zeros(n)
    R = l2sq / (l1 * linf)

    gL = np.zeros_like(L)
    gL[:-1] += (2.0 * a + b) / 3.0
    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = _conv(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]

    dlinf = e * (L - linf + alpha) / (alpha * Z)
    dlinf_c = dlinf[1:-1]
    conv2 = _conv(dlinf_c, h[::-1])
    glinf_h = 2.0 * conv2[n - 1: n - 1 + n]

    dl1 = 2.0 * s
    denom = l1 * linf
    gR = gl2sq / denom - l2sq * (dl1 * linf + l1 * glinf_h) / (denom * denom)
    return -R, -gR


def _upsample(start, N):
    if start is None:
        return np.ones(N)
    start = np.asarray(start, dtype=float)
    if start.size == 0:
        return np.ones(N)
    xs = np.linspace(0.0, 1.0, start.size)
    xt = np.linspace(0.0, 1.0, N)
    h = np.interp(xt, xs, start)
    if h.sum() <= 0:
        h = np.ones(N)
    return h


def _polish(h, maxiter=4000):
    N = h.size
    bounds = [(0.0, None)] * N
    try:
        res = minimize(_negR_grad, h, method='L-BFGS-B', jac=True,
                       bounds=bounds,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def _polish_tol(h, rel_tol, maxiter=1500, bounds=None):
    N = h.size
    if bounds is None:
        bounds = [(0.0, None)] * N
    try:
        res = minimize(_negR_grad_tol, h, method='L-BFGS-B', jac=True,
