    for f in (0.30, 0.20, 0.12, 0.07, 0.04, 0.02, 0.01, 1.0):
        if time.process_time() > deadline:
            break
        k = max(1, int(f * M))
        h = _polish_k(best_h, k, maxiter=800)
        consider(h)
        if time.process_time() > deadline:
            break
        h = _polish_tol(best_h, 1e-9, maxiter=400)
        consider(h)

    # Try higher N: upsample then polish, keeping the higher-N if better.
    for N2 in (2000, 2400, 2800, 3200):
        if time.process_time() > deadline:
            break
        h2 = _upsample(best_h, N2)
        consider(h2)
        for f in (0.10, 0.05, 0.02, 1.0):
            if time.process_time() > deadline:
                break
            k = max(1, int(f * (2 * N2 + 1)))
            h2 = _polish_k(h2, k, maxiter=600)
            consider(h2)
        if time.process_time() < deadline:
            h2 = _polish_tol(h2, 1e-9, maxiter=600)
            consider(h2)
        if time.process_time() < deadline:
            h2 = _polish(h2, maxiter=800)
            consider(h2)

    # Final exact-R polish.
    if time.process_time() < deadline:
        h = _polish(best_h, maxiter=1500)
        consider(h)

    # --- Experiment: parametric cosine-bump global search ---
    Np = 1600
    cands = []
    for L in np.arange(0.50, 0.80 + 1e-9, 0.02):
        for p in np.arange(0.5, 3.0 + 1e-9, 0.25):
            if time.process_time() > deadline:
                break
            h = _cos_bump(Np, L, p)
            r = _R(h)
            if np.isfinite(r):
                cands.append((r, L, p))
    cands.sort(reverse=True)
    top = cands[:5]

    best_param_h = None
    best_param_r = -np.inf
    for (r0, L0, p0) in top:
        if time.process_time() > deadline:
            break

        def negr(params):
            L, p = params
            if L <= 0.02 or p <= 0.01:
                return 1e10
            h = _cos_bump(Np, L, p)
            r = _R(h)
            if not np.isfinite(r):
                return 1e10
            return -r

        try:
            res = minimize(negr, np.array([L0, p0]), method='Nelder-Mead',
                           options={'maxiter': 300, 'xatol': 1e-4, 'fatol': 1e-12})
            L1, p1 = res.x
        except Exception:
            L1, p1 = L0, p0
        if L1 <= 0.02 or p1 <= 0.01:
            L1, p1 = L0, p0
        h = _cos_bump(Np, L1, p1)
        r = _R(h)
        if np.isfinite(r) and r > best_param_r:
            best_param_r = r
            best_param_h = h

    if best_param_h is not None:
        consider(best_param_h, best_param_r)

    # Regenerate best parametric shape at N=3200 and run ladder.
    if best_param_h is not None and time.process_time() < deadline:
        # recover (L,p) approximately by re-optimizing at N=3200 from upsampled
        N2 = 3200
        h2 = _upsample(best_param_h, N2)
        consider(h2)
        for alpha in np.geomspace(1e-3, 1e-8, 8):
            if time.process_time() > deadline:
                break
            h2 = _polish_soft(h2, alpha, maxiter=1000)
            consider(h2)
        for f in (0.3, 0.1, 0.03, 1.0):
            if time.process_time() > deadline:
                break
            k = max(1, int(f * (2 * N2 + 1)))
            h2 = _polish_k(h2, k, maxiter=800)
            consider(h2)
        if time.process_time() < deadline:
            h2 = _polish(h2, maxiter=1500)
            consider(h2)

    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(a, b):
    if a.size > 1500 or b.size > 1500:
        return fftconvolve(a, b)
    return np.convolve(a, b)


def _L_of(h):
    c = _conv(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    return L


def _R(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)):
        return -np.inf
    s = h.sum()
    if s <= 0:
        return -np.inf
    L = _L_of(h)
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    linf = L.max()
    if linf <= 0:
        return -np.inf
    return l2sq / (s * s * linf)


def _parts(h):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return None
    L = _L_of(h)
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    gL = np.zeros_like(L)
    gL[:-1] += (2.0 * a + b) / 3.0
    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = _conv(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]
    return h, n, s, L, l2sq, gl2sq


def _grad_from_parts(parts, linf):
    h, n, s, L, l2sq, gl2sq = parts
    dl1 = 2.0 * s
    # gradient of linf wrt h: for each max knot i, contribution 2*h[j] where j=k-i
    # Use exact max knots
    mx = L.max()
    active = np.where(L >= mx * (1.0 - 1e-12))[0]
    glinf_h = np.zeros(n)
    if active.size > 0:
        inv = 1.0 / active.size
        idx = np.arange(n)
        for i in active:
            if 1 <= i <= 2 * n - 1:
                k = i - 1
                j = k - idx
                valid = (j >= 0) & (j < n)
                glinf_h[valid] += 2.0 * h[j[valid]] * inv
    l1 = s * s
    denom = l1 * linf
    gR = gl2sq / denom - l2sq * (dl1 * linf + l1 * glinf_h) / (denom * denom)
    return gR


def _negR_grad(h):
    p = _parts(h)
    if p is None:
        return 1e10, np.zeros_like(h)
    h, n, s, L, l2sq, gl2sq = p
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return 1e10, np.zeros_like(h)
    R = l2sq / (l1 * linf)
    g = _grad_from_parts(p, linf)
    return -R, -g


def _negR_grad_soft(h, alpha):
    p = _parts(h)
    if p is None:
        return 1e10, np.zeros_like(h)
    h, n, s, L, l2sq, gl2sq = p
    l1 = s * s
    mx = L.max()
    e = np.exp((L - mx) / alpha)
    Z = e.sum()
    linf = (e * L).sum() / Z
    if linf <= 0:
        return 1e10, np.zeros_like(h)
    R = l2sq / (l1 * linf)
    dlinf = e * (L - linf + alpha) / (alpha * Z)
    dlinf_c = dlinf[1:-1]
    conv2 = _conv(dlinf_c, h[::-1])
    glinf_h = 2.0 * conv2[n - 1: n - 1 + n]
    dl1 = 2.0 * s
    denom = l1 * linf
    gR = gl2sq / denom - l2sq * (dl1 * linf + l1 * glinf_h) / (denom * denom)
    return -R, -gR


def _Rk_grad(h, k):
    p = _parts(h)
    if p is None:
        return 1e10, np.zeros_like(h)
    h, n, s, L, l2sq, gl2sq = p
    l1 = s * s
    m = L.size
    k = max(1, min(k, m))
    idx = np.argpartition(L, m - k)[m - k:]
    lk = L[idx].mean()
    if lk <= 0:
        return 1e10, np.zeros_like(h)
    Rk = l2sq / (l1 * lk)
    glk_h = np.zeros(n)
    inv_k = 1.0 / k
    for i in idx:
        if 1 <= i <= 2 * n - 1:
            kk = i - 1
            j = kk - np.arange(n)
            valid = (j >= 0) & (j < n)
            glk_h[valid] += 2.0 * h[j[valid]] * inv_k
    dl1 = 2.0 * s
    denom = l1 * lk
    gRk = gl2sq / denom - l2sq * (dl1 * lk + l1 * glk_h) / (denom * denom)
    return -Rk, -gRk


def _opt(func, h, args=(), maxiter=1500):
    N = h.size
    bounds = [(0.0, None)] * N
    try:
        res = minimize(func, h, method='L-BFGS-B', jac=True,
                       bounds=bounds, args=args,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def _resample(h, N):
    if h is None or h.size == 0:
        return np.ones(N)
    xs = np.linspace(0.0, 1.0, h.size)
    xt = np.linspace(0.0, 1.0, N)
    out = np.interp(xt, xs, h)
    if out.sum() <= 0:
        out = np.ones(N)
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 2.5)

    def time_left():
        return deadline - time.process_time()

    best_h = None
    best_r = -np.inf

    def consider(h):
        nonlocal best_h, best_r
        if h is None or h.size == 0:
            return False
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return False
        r = _R(h)
        if np.isfinite(r) and r > best_r + 1e-13:
            best_r = r
            best_h = h.copy()
            return True
        return False

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            consider(s / s.max())

    # The winning start was at N=800. Polish intensively at that resolution
    # using a ladder of soft-max and top-k objectives, then a final exact polish.
    baseN = best_h.size if best_h is not None else 800
    if baseN < 200:
        baseN = 800

    if best_h is None:
        best_h = np.ones(baseN)
        best_r = _R(best_h)

    # Phase 1: soft-max ladder (smooths the nonsmooth linf to escape kinks)
    for alpha in [1e-2, 3e-3, 1e-3, 3e-4, 1e-4, 3e-5, 1e-5, 3e-6, 1e-6]:
        if time_left() < 1.0:
            break
        h = _opt(_negR_grad_soft, best_h, args=(alpha,), maxiter=1200)
        consider(h)
        if time_left() < 0.5:
            break
        h = _opt(_negR_grad, h, maxiter=600)
        consider(h)

    # Phase 2: top-k widening — pushes a band of knots to near-maximum
    m = 2 * best_h.size + 1
    for f in [0.5, 0.35, 0.25, 0.18, 0.12, 0.08, 0.05, 0.03, 0.02, 0.01, 0.005]:
        if time_left() < 1.0:
            break
        k = max(1, int(f * m))
        h = _opt(_Rk_grad, best_h, args=(k,), maxiter=1000)
        consider(h)
        if time_left() < 0.5:
            break
        h = _opt(_negR_grad, h, maxiter=500)
        consider(h)

    # Phase 3: alternate exact and soft at fine scale
    for alpha in [3e-6, 1e-6, 3e-7, 1e-7]:
        if time_left() < 1.0:
            break
        h = _opt(_negR_grad_soft, best_h, args=(alpha,), maxiter=800)
        consider(h)
        h = _opt(_negR_grad, h, maxiter=500)
        consider(h)

    # Phase 4: greedy cycle of top-k refinements around the current best
    stall = 0
    while time_left() > 1.5 and stall < 3:
        improved = False
        for f in [0.06, 0.04, 0.025, 0.015, 0.008]:
            if time_left() < 1.0:
                break
            m = 2 * best_h.size + 1
            k = max(1, int(f * m))
            h = _opt(_Rk_grad, best_h, args=(k,), maxiter=800)
            if consider(h):
                improved = True
            if time_left() < 0.5:
                break
            h = _opt(_negR_grad, best_h, maxiter=600)
            if consider(h):
                improved = True
        if improved:
            stall = 0
        else:
            stall += 1

    if best_h is None:
        best_h = np.ones(baseN)
    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(a, b):
    if a.size > 2000 or b.size > 2000:
        return fftconvolve(a, b)
    return np.convolve(a, b)


def _R(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)):
        return -np.inf
    s = h.sum()
    if s <= 0:
        return -np.inf
    c = _conv(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    linf = L.max()
    if linf <= 0:
        return -np.inf
    return l2sq / (s * s * linf)


def _R_grad(h, rel_tol=1e-9):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return -np.inf, np.zeros(n)
    c = _conv(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -np.inf, np.zeros(n)
    R = l2sq / (l1 * linf)

    gL = np.zeros_like(L)
    gL[:-1] += (2.0 * a + b) / 3.0
    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = _conv(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]

    dl1 = 2.0 * s

    glinf_h = np.zeros(n)
    active = np.where(L >= linf * (1.0 - rel_tol))[0]
    if active.size > 0:
        inv = 1.0 / active.size
        idx = np.arange(n)
        for i in active:
            if 1 <= i <= 2 * n - 1:
                k = i - 1
                j = k - idx
                valid = (j >= 0) & (j < n)
                glinf_h[valid] += 2.0 * h[j[valid]] * inv

    denom = l1 * linf
    gR = gl2sq / denom - l2sq * (dl1 * linf + l1 * glinf_h) / (denom * denom)
    return R, gR


def _negR_grad(h):
    R, g = _R_grad(h, 1e-9)
    if not np.isfinite(R):
        return 1e10, np.zeros_like(h)
    return -R, -g


def _negR_grad_tol(h, rel_tol):
    R, g = _R_grad(h, rel_tol)
    if not np.isfinite(R):
        return 1e10, np.zeros_like(h)
    return -R, -g


def _negR_grad_soft(h, alpha):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return 1e10, np.zeros(n)
    c = _conv(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    mx = L.max()
    e = np.exp((L - mx) / alpha)
    Z = e.sum()
    linf = (e * L).sum() / Z
    if linf <= 0:
        return 1e10, np.zeros(n)
    R = l2sq / (l1 * linf)

    gL = np.zeros_like(L)
    gL[:-1] += (2.0 * a + b) / 3.0
    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = _conv(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]

    dlinf = e * (L - linf + alpha) / (alpha * Z)
    dlinf_c = dlinf[1:-1]
    conv2 = _conv(dlinf_c, h[::-1])
    glinf_h = 2.0 * conv2[n - 1: n - 1 + n]

    dl1 = 2.0 * s
    denom = l1 * linf
    gR = gl2sq / denom - l2sq * (dl1 * linf + l1 * glinf_h) / (denom * denom)
    return -R, -gR


def _upsample(start, N):
    if start is None:
        return np.ones(N)
    start = np.asarray(start, dtype=float)
    if start.size == 0:
        return np.ones(N)
    xs = np.linspace(0.0, 1.0, start.size)
    xt = np.linspace(0.0, 1.0, N)
    h = np.interp(xt, xs, start)
    if h.sum() <= 0:
        h = np.ones(N)
    return h


def _polish(h, maxiter=4000, bounds=None):
    N = h.size
    if bounds is None:
        bounds = [(0.0, None)] * N
    try:
        res = minimize(_negR_grad, h, method='L-BFGS-B', jac=True,
                       bounds=bounds,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def _polish_tol(h, rel_tol, maxiter=1500, bounds=None):
    N = h.size
    if bounds is None:
        bounds = [(0.0, None)] * N
    try:
        res = minimize(_negR_grad_tol, h, method='L-BFGS-B', jac=True,
                       bounds=bounds, args=(rel_tol,),
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def _polish_soft(h, alpha, maxiter=1500, bounds=None):
    N = h.size
    if bounds is None:
        bounds = [(0.0, None)] * N
    try:
        res = minimize(_negR_grad_soft, h, method='L-BFGS-B', jac=True,
                       bounds=bounds, args=(alpha,),
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def _Rk_grad(h, k):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return 1e10, np.zeros(n)
    c = _conv(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    m = L.size
    k = max(1, min(k, m))
    idx = np.argpartition(L, m - k)[m - k:]
    lk = L[idx].mean()
    if lk <= 0:
        return 1e10, np.zeros(n)
    Rk = l2sq / (l1 * lk)

    gL = np.zeros_like(L)
    gL[:-1] += (2.0 * a + b) / 3.0
    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = _conv(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]

    dl1 = 2.0 * s
    glk_h = np.zeros(n)
    inv_k = 1.0 / k
    for i in idx:
        if 1 <= i <= 2 * n - 1:
            kk = i - 1
            j = kk - np.arange(n)
            valid = (j >= 0) & (j < n)
            glk_h[valid] += 2.0 * h[j[valid]] * inv_k

    denom = l1 * lk
    gRk = gl2sq / denom - l2sq * (dl1 * lk + l1 * glk_h) / (denom * denom)
    return -Rk, -gRk


def _polish_k(h, k, maxiter=3000, bounds=None):
    N = h.size
    if bounds is None:
        bounds = [(0.0, None)] * N
    try:
        res = minimize(_Rk_grad, h, method='L-BFGS-B', jac=True,
                       bounds=bounds, args=(k,),
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 4.0)

    def now():
        return time.process_time()

    best_h = _upsample(start, 1600)
    best_r = _R(best_h)
    if not np.isfinite(best_r):
        best_r = -np.inf

    def consider(h, r=None):
        nonlocal best_h, best_r
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return False
        if r is None:
            r = _R(h)
        if np.isfinite(r) and r > best_r:
            best_r = r
            best_h = h.copy()
            return True
        return False

    # --- Stage 1: refine at the start's native resolution, freezing zeros ---
    # The start's zeros are structural (support gaps); preserve them exactly.
    if start is not None:
        s0 = np.asarray(start, dtype=float)
        if s0.size > 0:
            base = s0.copy()
            zbound = [(0.0, 0.0) if base[i] <= 0.0 else (0.0, None)
                      for i in range(base.size)]
            cur = base
            for tol in (1e-5, 1e-7, 1e-9, 1e-10):
                if now() > deadline:
                    break
                cur = _polish_tol(cur, tol, maxiter=600, bounds=zbound)
                consider(cur)
            for alpha in (1e-5, 1e-6, 1e-7):
                if now() > deadline:
                    break
                cur = _polish_soft(cur, alpha, maxiter=500, bounds=zbound)
                consider(cur)
            if now() < deadline:
                cur = _polish_k(cur, max(1, int(0.01 * (2 * cur.size + 1))),
                                maxiter=500, bounds=zbound)
                consider(cur)
            if now() < deadline:
                cur = _polish(cur, maxiter=800, bounds=zbound)
                consider(cur)

    # --- Stage 2: exact replication (integer upsample) with frozen zeros ---
    # Replicating by factor k multiplies knot count but preserves R exactly,
    # giving a strictly finer grid to break symmetry on.
    def refine_replicate(base_h, factor):
        h2 = np.repeat(np.asarray(base_h, dtype=float), factor)
        consider(h2)
        bounds = [(0.0, 0.0) if h2[i] == 0.0 else (0.0, None)
                  for i in range(h2.size)]
        cur = h2
        # Break ties on the finer grid with top-k smoothing first.
        for f in (0.02, 0.01, 0.005):
            if now() > deadline:
                return
            k = max(1, int(f * (2 * cur.size + 1)))
            cur = _polish_k(cur, k, maxiter=400, bounds=bounds)
            consider(cur)
        for tol in (1e-6, 1e-9, 1e-10):
            if now() > deadline:
                return
            cur = _polish_tol(cur, tol, maxiter=400, bounds=bounds)
            consider(cur)
        for alpha in (1e-6, 1e-7):
            if now() > deadline:
                return
            cur = _polish_soft(cur, alpha, maxiter=400, bounds=bounds)
            consider(cur)
        if now() < deadline:
            cur = _polish(cur, maxiter=600, bounds=bounds)
            consider(cur)

    # Try factor 2 then 4 on the current best (which may still be the start).
    if now() < deadline:
        refine_replicate(best_h, 2)
    if now() < deadline:
        refine_replicate(best_h, 4)

    # --- Stage 3: short global polish ladder on the best-so-far ---
    for tol in (1e-5, 1e-9, 1e-10):
        if now() > deadline:
            break
        h = _polish_tol(best_h, tol, maxiter=400)
        consider(h)
    if now() < deadline:
        h = _polish(best_h, maxiter=800)
        consider(h)

    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(a, b):
    if a.size > 1200 or b.size > 1200:
        return fftconvolve(a, b)
    return np.convolve(a, b)


def _L_of(h):
    c = _conv(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    return L


def _R(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)):
        return -np.inf
    s = h.sum()
    if s <= 0:
        return -np.inf
    L = _L_of(h)
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    linf = L.max()
    if linf <= 0:
        return -np.inf
    return l2sq / (s * s * linf)


def _parts(h):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return None
    L = _L_of(h)
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    gL = np.zeros_like(L)
    gL[:-1] += (2.0 * a + b) / 3.0
    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = _conv(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]
    return h, n, s, L, l2sq, gl2sq


def _grad_exact(p):
    h, n, s, L, l2sq, gl2sq = p
    linf = L.max()
    if linf <= 0:
        return None
    mx = linf
    active = np.where(L >= mx * (1.0 - 1e-11))[0]
    glinf_h = np.zeros(n)
    if active.size > 0:
        inv = 1.0 / active.size
        idx = np.arange(n)
        for i in active:
            if 1 <= i <= 2 * n - 1:
                k = i - 1
                j = k - idx
                valid = (j >= 0) & (j < n)
                glinf_h[valid] += 2.0 * h[j[valid]] * inv
    l1 = s * s
    denom = l1 * linf
    gR = gl2sq / denom - l2sq * (2.0 * s * linf + l1 * glinf_h) / (denom * denom)
    return gR


def _negR_grad(h):
    p = _parts(h)
    if p is None:
        return 1e10, np.zeros_like(h)
    h, n, s, L, l2sq, gl2sq = p
    linf = L.max()
    if linf <= 0:
        return 1e10, np.zeros_like(h)
    R = l2sq / (s * s * linf)
    g = _grad_exact(p)
    if g is None:
        return 1e10, np.zeros_like(h)
    return -R, -g


def _negR_grad_soft(h, alpha):
    p = _parts(h)
    if p is None:
        return 1e10, np.zeros_like(h)
    h, n, s, L, l2sq, gl2sq = p
    l1 = s * s
    mx = L.max()
    e = np.exp((L - mx) / alpha)
    Z = e.sum()
    linf = (e * L).sum() / Z
    if linf <= 0:
        return 1e10, np.zeros_like(h)
    R = l2sq / (l1 * linf)
    dlinf = e * (L - linf + alpha) / (alpha * Z)
    dlinf_c = dlinf[1:-1]
    conv2 = _conv(dlinf_c, h[::-1])
    glinf_h = 2.0 * conv2[n - 1: n - 1 + n]
    dl1 = 2.0 * s
    denom = l1 * linf
    gR = gl2sq / denom - l2sq * (dl1 * linf + l1 * glinf_h) / (denom * denom)
    return -R, -gR


def _Rk_grad(h, k):
    p = _parts(h)
    if p is None:
        return 1e10, np.zeros_like(h)
    h, n, s, L, l2sq, gl2sq = p
    l1 = s * s
    m = L.size
    k = max(1, min(k, m))
    idx = np.argpartition(L, m - k)[m - k:]
    lk = L[idx].mean()
    if lk <= 0:
        return 1e10, np.zeros_like(h)
    Rk = l2sq / (l1 * lk)
    glk_h = np.zeros(n)
    inv_k = 1.0 / k
    for i in idx:
        if 1 <= i <= 2 * n - 1:
            kk = i - 1
            j = kk - np.arange(n)
            valid = (j >= 0) & (j < n)
            glk_h[valid] += 2.0 * h[j[valid]] * inv_k
    dl1 = 2.0 * s
    denom = l1 * lk
    gRk = gl2sq / denom - l2sq * (dl1 * lk + l1 * glk_h) / (denom * denom)
    return -Rk, -gRk


def _opt(func, h, args=(), maxiter=1500):
    N = h.size
    bounds = [(0.0, None)] * N
    try:
        res = minimize(func, h, method='L-BFGS-B', jac=True,
                       bounds=bounds, args=args,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def _resample(h, N):
    if h is None or h.size == 0:
        return np.ones(N)
    xs = np.linspace(0.0, 1.0, h.size)
    xt = np.linspace(0.0, 1.0, N)
    out = np.interp(xt, xs, h)
    if out.sum() <= 0:
        out = np.ones(N)
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 2.5)

    def time_left():
        return deadline - time.process_time()

    best_h = None
    best_r = -np.inf

    def consider(h):
        nonlocal best_h, best_r
        if h is None or h.size == 0:
            return False
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return False
        r = _R(h)
        if np.isfinite(r) and r > best_r + 1e-13:
            best_r = r
            best_h = h.copy()
            return True
        return False

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            consider(s / s.max())

    baseN = best_h.size if best_h is not None else 2000
    if best_h is None:
        best_h = np.ones(baseN)
        best_r = _R(best_h)

    # Phase 1: soft-max ladder to escape nonsmooth kinks at native N
    for alpha in [1e-2, 3e-3, 1e-3, 3e-4, 1e-4, 3e-5, 1e-5, 3e-6, 1e-6, 3e-7]:
        if time_left() < 1.0:
            break
        h = _opt(_negR_grad_soft, best_h, args=(alpha,), maxiter=1000)
        consider(h)
        if time_left() < 0.4:
            break
        h = _opt(_negR_grad, h, maxiter=400)
        consider(h)

    # Phase 2: top-k widening
    m = 2 * best_h.size + 1
    for f in [0.4, 0.28, 0.2, 0.14, 0.09, 0.06, 0.04, 0.025, 0.015, 0.008]:
        if time_left() < 1.0:
            break
        k = max(1, int(f * m))
        h = _opt(_Rk_grad, best_h, args=(k,), maxiter=800)
        consider(h)
        if time_left() < 0.4:
            break
        h = _opt(_negR_grad, best_h, maxiter=500)
        consider(h)

    # Phase 3: try upsampled resolutions -- finer grid reduces staircase error
    for mult in (1.5, 2.0, 3.0, 1.25):
        if time_left() < 3.0:
            break
        N = int(min(50000, max(1, round(baseN * mult))))
        h = _resample(best_h, N)
        for _ in range(2):
            if time_left() < 1.5:
                break
            h = _opt(_negR_grad, h, maxiter=800)
            consider(h)
            if time_left() < 0.5:
                break
        # soft ladder at new resolution
        for alpha in [1e-4, 3e-5, 1e-5, 3e-6, 1e-6]:
            if time_left() < 1.0:
                break
            h = _opt(_negR_grad_soft, h, args=(alpha,), maxiter=600)
            consider(h)
            h = _opt(_negR_grad, h, maxiter=400)
            consider(h)

    # Phase 4: greedy cycle at current best resolution
    stall = 0
    while time_left() > 1.5 and stall < 3:
        improved = False
        Ncur = best_h.size
        m = 2 * Ncur + 1
        for f in [0.05, 0.03, 0.02, 0.012, 0.007]:
            if time_left() < 1.0:
                break
            k = max(1, int(f * m))
            h = _opt(_Rk_grad, best_h, args=(k,), maxiter=700)
            if consider(h):
                improved = True
            if time_left() < 0.4:
                break
            h = _opt(_negR_grad, best_h, maxiter=500)
            if consider(h):
                improved = True
        # extra soft polish
        for alpha in [3e-6, 1e-6, 3e-7]:
            if time_left() < 1.0:
                break
            h = _opt(_negR_grad_soft, best_h, args=(alpha,), maxiter=500)
            consider(h)
            h = _opt(_negR_grad, h, maxiter=400)
            if consider(h):
                improved = True
        if improved:
            stall = 0
        else:
            stall += 1

    if best_h is None:
        best_h = np.ones(baseN)
    return np.asarray(best_h, dtype=float)

import numpy as np
