    gL[1:] += (a + 2.0 * b) / 3.0
    gc = gL[1:-1]
    conv = _conv(gc, h[::-1])
    gl2sq = 2.0 * conv[n - 1: n - 1 + n]
    return h, n, s, L, l2sq, gl2sq


def _grad_from_parts(parts, linf):
    h, n, s, L, l2sq, gl2sq = parts
    dl1 = 2.0 * s
    mx = L.max()
    active = np.where(L >= mx * (1.0 - 1e-12))[0]
    glinf_h = np.zeros(n)
    if active.size > 0:
        inv = 1.0 / active.size
        for i in active:
            if 1 <= i <= 2 * n - 1:
                k = i - 1
                j = k - np.arange(n)
