def _opt(func, h, args=(), maxiter=1500, bounds=None):
    N = h.size
    if bounds is None:
        bounds = [(0.0, None)] * N
    try:
        res = minimize(func, h, method='L-BFGS-B', jac=True,
                       bounds=bounds, args=args,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 100,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def _resample(h, N):
    if h is None or h.size == 0:
        return np.ones(N)
    xs = np.linspace(0.0, 1.0, h.size)
    xt = np.linspace(0.0, 1.0, N)
    out = np.interp(xt, xs, h)
    if out.sum() <= 0:
        out = np.ones(N)
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 2.5)

    def time_left():
        return deadline - time.process_time()

    best_h = None
    best_r = -np.inf

    def consider(h):
        nonlocal best_h, best_r
        if h is None or h.size == 0:
            return False
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return False
        r = _R(h)
        if np.isfinite(r) and r > best_r + 1e-13:
            best_r = r
            best_h = h.copy()
            return True
        return False

    # Seed from start (preserve its structure/zeros)
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            consider(s / s.max())

    if best_h is None:
        best_h = np.ones(800)
        best_r = _R(best_h)

    # Freeze structural zeros from the start (if any)
    frozen = None
    if start is not None:
        s0 = np.asarray(start, dtype=float)
        if s0.size == best_h.size:
            frozen = s0 <= 0.0

    def bounds_for(h):
        if frozen is not None and frozen.size == h.size:
            return [(0.0, 0.0) if frozen[i] else (0.0, None)
                    for i in range(h.size)]
        return None

    # Phase 1: soft-max ladder at native resolution
    for alpha in [1e-2, 3e-3, 1e-3, 3e-4, 1e-4, 3e-5, 1e-5, 3e-6, 1e-6]:
        if time_left() < 1.0:
            break
        h = _opt(_negR_grad_soft, best_h, args=(alpha,), maxiter=1200,
                 bounds=bounds_for(best_h))
        consider(h)
        if time_left() < 0.5:
            break
        h = _opt(_negR_grad, h, maxiter=600, bounds=bounds_for(h))
        consider(h)

    # Phase 2: top-k widening
    m = 2 * best_h.size + 1
    for f in [0.5, 0.35, 0.25, 0.18, 0.12, 0.08, 0.05, 0.03, 0.02, 0.01, 0.005]:
        if time_left() < 1.0:
            break
        k = max(1, int(f * (2 * best_h.size + 1)))
        h = _opt(_Rk_grad, best_h, args=(k,), maxiter=1000,
                 bounds=bounds_for(best_h))
        consider(h)
        if time_left() < 0.5:
            break
        h = _opt(_negR_grad, h, maxiter=500, bounds=bounds_for(h))
        consider(h)

    # Phase 3: alternate exact and soft at fine scale
    for alpha in [3e-6, 1e-6, 3e-7, 1e-7]:
        if time_left() < 1.0:
            break
        h = _opt(_negR_grad_soft, best_h, args=(alpha,), maxiter=800,
                 bounds=bounds_for(best_h))
        consider(h)
        h = _opt(_negR_grad, h, maxiter=500, bounds=bounds_for(h))
        consider(h)

    # Phase 4: greedy cycle of top-k refinements
    stall = 0
    while time_left() > 1.5 and stall < 3:
        improved = False
        for f in [0.06, 0.04, 0.025, 0.015, 0.008]:
            if time_left() < 1.0:
                break
            k = max(1, int(f * (2 * best_h.size + 1)))
            h = _opt(_Rk_grad, best_h, args=(k,), maxiter=800,
                     bounds=bounds_for(best_h))
            if consider(h):
                improved = True
            if time_left() < 0.5:
                break
            h = _opt(_negR_grad, best_h, maxiter=600,
                     bounds=bounds_for(best_h))
            if consider(h):
                improved = True
        if improved:
            stall = 0
        else:
            stall += 1

    return np.asarray(best_h, dtype=float)
